  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-menu:where([data-slot="select"], [data-slot^="select-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where([data-slot="select"], [data-slot^="select-"]) {
  scrollbar-gutter: stable;
}
.v-select:where([data-slot="select"], [data-slot^="select-"]) {
