  background: var(--v-ink);
  box-shadow: inset 0 0 0 2px var(--v-pink);
}
.v-select:where(
    [data-slot="select"],
    [data-slot^="select-"]
  ).-ink[aria-expanded="true"]
  > .v-icon:last-child {
  color: var(--v-pink);
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block {
  width: 100%;
  height: 52px;
  padding: 0 8px 0 8px;
  font-size: var(--fs-body);
  font-weight: 500;
  background: var(--input);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block
  > span:first-child {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block
  > span:first-child
  > [data-value],
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block
  > span:first-child
  > span:not(.v-disk) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block .v-disk {
  width: 36px;
  height: 36px;
  flex: none;
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block
  .v-disk
  .v-icon {
  width: 17px;
  height: 17px;
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-block
  > .v-icon:last-child {
  width: 28px;
  height: 28px;
  padding: 7px;
  border-radius: 50%;
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1px var(--v-border);
  color: var(--v-text);
  stroke-width: 2.2;
  flex: none;
}
.v-select:where(
