  background: color-mix(in oklab, var(--input) 90%, var(--v-canvas));
}
.v-select:where(
    [data-slot="select"],
    [data-slot^="select-"]
  ).-block[aria-expanded="true"] {
  background: var(--v-pink-soft);
}
.v-select:where([data-slot="select"], [data-slot^="select-"]).-sm {
  height: 32px;
