  font-size: 13px;
}
.v-select:where([data-slot="select"], [data-slot^="select-"]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"]) {
  padding: 6px;
  border-radius: 18px;
  box-shadow:
    var(--shadow-float),
    inset 0 0 0 1px var(--v-border);
  border: 0;
  display: grid;
  gap: 2px;
  min-width: max(100%, 220px);
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"]) .v-menu__item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 42px;
  padding: 0 10px 0 8px;
  border-radius: 12px;
  font-size: 14.5px;
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item:not(:has(.v-disk,.v-item-adornment)) {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-left: 12px;
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item
