  width: 28px;
  height: 28px;
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item
  .v-disk
  .v-icon {
  width: 15px;
  height: 15px;
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item:hover {
  background: var(--v-beige);
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item[data-state="checked"] {
  background: var(--v-pink-soft);
  color: var(--v-text);
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item[data-state="checked"]::after {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--v-pink-deep);
  margin: 0;
  justify-self: end;
}
.v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
:root[data-mode="dark"]
  .v-select:where([data-slot="select"], [data-slot^="select-"]):not(.-ink) {
  background: var(--v-beige);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
:root[data-mode="dark"]
  .v-select:where([data-slot="select"], [data-slot^="select-"]).-block
  > .v-icon:last-child {
  background: var(--v-beige-2);
  box-shadow: none;
  color: var(--v-text);
}
:root[data-mode="dark"]
  .v-listbox:where([data-slot="select"], [data-slot^="select-"]) {
  background: var(--v-beige);
}
:root[data-mode="dark"]
  .v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item:hover {
  background: var(--v-beige-2);
}
:root[data-mode="dark"]
  .v-listbox:where([data-slot="select"], [data-slot^="select-"])
  .v-menu__item[data-state="checked"] {
  background: color-mix(in oklab, var(--v-pink) 22%, var(--v-canvas));
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="select"],
  [data-slot^="select-"],
  [data-slot="select"]::before,
  [data-slot="select"]::after,
  [data-slot^="select-"]::before,
  [data-slot^="select-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="select-content"] {
  min-width: max(var(--radix-select-trigger-width, 0px), 220px);
  max-height: var(--radix-select-content-available-height);
  max-width: calc(100vw - 24px);
}
[data-slot="select-viewport"] {
  display: grid;
  gap: 2px;
}
[data-slot="select-item"][data-disabled] {
  pointer-events: none;
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
[data-slot="select-item"][data-highlighted] {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

/* The source focuses a native option button on pointer open. Radix focuses a
   div, which Chromium marks focus-visible; retain the source pointer appearance
   and reveal its authored focus ring as soon as keyboard navigation begins. */
.v-listbox:where([data-slot="select-content"])[data-pointer-interaction] .v-menu__item:focus-visible {
  outline: 3px none currentColor;
  outline-offset: 0;
}

/* Disabled paint wins over variant, open, hover, and theme rules. */
:root [data-slot="select-trigger"].v-select:disabled { background: var(--v-disabled-face); color: var(--v-disabled-ink); box-shadow: inset 0 0 0 1px var(--v-disabled-edge); }

/* Nested menus live above dialog surfaces as well as the document. */
[data-slot="select-content"] { z-index: var(--z-popover); }

/* The label owns the flexible column; decorative identity never enters ItemText. */
[data-slot="select-item"] { grid-template-columns:30px minmax(0,1fr) auto; min-height:44px; }
[data-slot="select-item"]:not(:has(.v-item-adornment,.v-disk)) { grid-template-columns:minmax(0,1fr) auto; }
[data-slot="select-item"] > .v-item-adornment { grid-column:1; }
[data-slot="select-item"] > span:not(.v-item-adornment) { min-width:0; overflow-wrap:anywhere; }
[data-slot="select-content"] { width:var(--menu-width,max(var(--radix-select-trigger-width,0px),240px)); min-width:0; max-width:calc(100vw - 24px); }
[data-slot="select-trigger"] > .v-state-chevron { margin-inline-start:auto; }
[data-slot="select-trigger"]:active:not(:disabled) { background:var(--v-pink-soft); color:var(--v-text); }

}
